-- =============================================================================
-- 0005 — Starter Island rebalance (missions 5–24)
--
-- Apply after 0004:
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f database/migrations/0005_starter_island_rebalance.sql
-- (or paste into the Neon SQL Editor). One transaction; safe to run again.
--
-- A real difficulty curve: missions 1–4 stay short; 5–24 get longer routes and
-- harder logic (45° turns, loops, sensors, nested ifs, variables, counting, a
-- real maze, line following with detours) and mission 24 becomes a whole
-- city district (new environment `starter-rescue-city`).
--
-- Student progress on these levels (status, stars, XP) is kept. Objective
-- ticks for the redesigned levels are reset, because their objectives changed.
-- =============================================================================
BEGIN;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM levels WHERE slug = 'starter-24') THEN
    RAISE EXCEPTION '0005 needs migration 0004 (starter-24 is missing)';
  END IF;
END $$;

INSERT INTO environments (id, name, kind, theme, description, config, status)
VALUES ('starter-rescue-city', 'Rescue City', 'LEVEL', 'starter', 'A whole city district: junction signals, roadworks, survivors to rescue and Rescue HQ.', '{"lighting":"warmAfternoon","chase":{"back":2.3,"height":2.8,"side":0.8}}'::jsonb, 'PUBLISHED')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, description = EXCLUDED.description, config = EXCLUDED.config, status = 'PUBLISHED';

