UPDATE levels SET title = 'Sensor Basics', brief_description = 'Meet the obstacle sensor: the trail spirals in to the ranger hut and no two sides are the same length. Let the sensor tell you when to turn.',
       description = 'Meet the obstacle sensor: the trail spirals in to the ranger hut and no two sides are the same length. Let the sensor tell you when to turn. Environment: Ranger Hut — A log-lined forest path ending at the ranger’s hut.',
       difficulty = 'MEDIUM', environment_id = 'starter-ranger-hut', estimated_minutes = 13,
