UPDATE levels SET title = 'Complex Route', brief_description = 'Switchbacks down the gorge: each run is 60 cm shorter than the last. A variable for the run length, a loop for the pattern, the sensor for the gate.',
       description = 'Switchbacks down the gorge: each run is 60 cm shorter than the last. A variable for the run length, a loop for the pattern, the sensor for the gate. Environment: Gorge Run — Zigzags down the canyon, a steel bridge over the gorge and a gate.',
